Ext._define('rh.registration.forminformation.general.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.registration.forminformation.general.Window',

    hideItemsToolbar: ['add', 'remove'],
    hideActions: ['remove', 'copy', 'edit'],
    configOrderToolBar: ['edit', 'sendValidationAct', 'undo_send_validation', '-', 'activeAction', '-', 'search'],

    getColumnModel: function () {
        if (!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    // { header: '', dataIndex: 'icons', width: 60, 'renderer': adm.daily.rendererIconGrid },
                    { header: 'Chave', dataIndex: 'pk', width: 60 },
                    { header: 'Matricula/Servidor', dataIndex: 'description', id: 'autoExpandColumn' },
                    { header: 'Estado', dataIndex: 'state_display', width: 200 },
                    { header: 'Última validação', dataIndex: 'validated_by_unicode', width: 200 },
                    { header: 'Data de Validação', dataIndex: 'validated_at', width: 100, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i') },
                    { header: 'Criado por', dataIndex: 'created_by_unicode', width: 120, sortable: true, hidden: true },
                    { header: 'Criado em', dataIndex: 'created_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), sortable: true, hidden: true },
                    { header: 'Recebido por', dataIndex: 'received_by_unicode', width: 120, sortable: true },
                    { header: 'Recebido em', dataIndex: 'received_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), sortable: true },
                    { header: 'Modificado por', dataIndex: 'modified_by_unicode', width: 120, sortable: true, hidden: true },
                    { header: 'Modificado em', dataIndex: 'modified_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), sortable: true, hidden: true },
                    { header: 'Enviado por', dataIndex: 'sent_by_unicode', width: 120, sortable: true, hidden: true },
                    { header: 'Enviado em', dataIndex: 'sent_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), sortable: true, hidden: true }
                ]
            );
        return this._columnModel;
    },

    getConfigActionsItems: function (cfg) {
        var menu = rh.registration.forminformation.general.Grid.superclass.getConfigActionsItems.call(this, cfg);
        menu.edit.text = 'Atualizar Dados Pessoais';
        menu['sendValidationAct'] = {
            text: 'Enviar para Validação',
            iconCls: 'icon-rh icon-core-publication-confirmed',
            scope: this,
            handler: function () { this.sendValidationAct() }
        };
        menu['undo_send_validation'] = {
            text: 'Desfazer Envio',
            iconCls: 'icon-core icon-core-remove-selected',
            scope: this,
            handler: function () { this.undo_send_validation() }
        };
        menu['activeAction'] = {
            text: 'Ativar/Desativar',
            iconCls: 'icon-registration icon-published',
            scope: this,
            handler: function() { this.changeActive() }
        };
        return menu;
    },

    undo_send_validation: function () {
        var selected = this.getSelectionModel().getSelected();

        if (!selected) {
            Ext.Msg.show({
                'title': this.title,
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK,
                'msg': 'Selecione uma matricula!'
            });
            return;
        }


        if (selected && selected.get('state') != 2) {
            var msg = 'Cadastro já está com servidor.';
            if (selected.get('state') == 3)
                msg = 'Dados já foram recebidos pelo DGPFP, nesse caso é preciso aguardar a validação.';
            Ext.Msg.show({
                'title': this.title,
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK,
                'msg': msg
            });
            return;
        }

        Ext.Msg.show({
            scope: this,
            title: 'PERGUNTA',
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.OKCANCEL,
            style: 'background-color: yellow',
            msg: 'Deseja realmente desfazer envio do formulário?',
            fn: function (button) {
                if (button == 'ok') {
                    Ext.Ajax.request({
                        url: toolkit.util.Normalize.controller_action(
                            'RegistrationFormInformation',
                            'undo_send_validation'
                        ),
                        params: { form: selected.get('pk') },
                        success: function (request) {
                            var obj = Ext.decode(request.responseText);
                            if (obj.success) {
                                this.getStore().reload();
                                if (obj.message != undefined && obj.message != '')
                                    Ext.Msg.show({
                                        'title': this.title,
                                        'icon': Ext.Msg.INFO,
                                        'buttons': Ext.Msg.OK,
                                        'msg': obj.message
                                    });
                            }
                            else if (obj.message != undefined && obj.message != '') {
                                Ext.Msg.show({
                                    'title': this.title,
                                    'icon': Ext.Msg.INFO,
                                    'buttons': Ext.Msg.OK,
                                    'msg': obj.message
                                });
                            }
                        },
                        failure: function () {
                            Ext.Msg.show({
                                'title': this.title,
                                'icon': Ext.Msg.INFO,
                                'buttons': Ext.Msg.OK,
                                'msg': 'Erro desfazer envio.'
                            });
                        },
                        scope: this
                    });
                }
            },
        });
    },

    sendValidationAct: function () {
        var selected = this.getSelectionModel().getSelected();

        if (!selected) {
            Ext.Msg.show({
                'title': this.title,
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK,
                'msg': 'Selecione uma matricula!'
            });
            return;
        }

        if (selected && (selected.get('state') != 1) && (selected.get('state') != 4) && (selected.get('state') != 5)) {
            Ext.Msg.show({
                'title': this.title,
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK,
                'msg': 'Dados já estão em validação.'
            });
            return;
        }
        this.sendValidation(selected.get('pk'));
    },

    sendValidation: function (formInformation, window) {
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(
                'RegistrationFormInformation',
                'send_validation'
            ),
            params: { form_information: formInformation },
            success: function (request) {
                var obj = Ext.decode(request.responseText);
                if (obj.success) {
                    this.getStore().reload();
                    if (window != undefined)
                        window.destroy();
                } else {
                    var message = this.getSelectionModel().getSelected().get('pendency');
                    if (message == '' || message == undefined) {
                        try {
                            var rs = Ext.decode(obj.message);
                            Object.keys(rs).forEach(function (key) {
                                message += rs[key];
                            });
                        } catch (error) {
                            message = obj.message;
                        }
                    }
                    Ext.Msg.show({
                        title: this.title,
                        icon: Ext.Msg.INFO,
                        buttons: Ext.Msg.OK,
                        msg: message
                    });
                }
            },
            failure: function (request) {
                var obj = Ext.decode(request.responseText);
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.INFO,
                    buttons: Ext.Msg.OK,
                    msg: obj.message
                });
            },
            scope: this
        });
    },

    _updateItemCustom: function (record) {
        var selected = core.nullValue(this.getSelectionModel().getSelected(), false);
        if (!selected) {
            Ext.Msg.show({
                'title': this.title,
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK,
                'msg': 'Selecione uma matricula!'
            });
            return;
        }

        if (selected && (selected.get('state') == 2)) {
            Ext.Msg.show({
                'title': this.title,
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK,
                'msg': 'Necessário desfazer envio ao DGPFP antes de editar novamente.'
            });
            return;
        }

        if (selected && (selected.get('state') == 3)) {
            Ext.Msg.show({
                'title': this.title,
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK,
                'msg': 'Não é possivel atualizar seus dados antes do DGPFP validar.'
            });
            return;
        }
        return rh.registration.forminformation.general.Grid.superclass.updateItem.call(this, record);
    },

    updateItem: function (record) {
        return this._updateItemCustom(record);
    },

    changeActive: function(){
        var sels = this.getSelectionModel().getSelections();
        var toAct = []
        Ext.each(sels, function(record) {
            toAct.push(record.get('pk'))
        });

        var lm = new Ext.LoadMask(this.getEl(), {
            msg: 'Recebendo as informações selecionadas...'
        });
        Ext.Ajax.request({
            scope: this,
            url: toolkit.util.Normalize.controller_action('RegistrationFormInformationAdmin', 'change_active'),
            params: { pk: toAct },
            success: function(request) {
                lm.hide();
                this.getStore().reload();
                var rst = Ext.decode(request.responseText);
                if(rst.success == false)
                    Ext.Msg.show({
                        title: 'Item de solicitação',
                        msg: rst.message,
                        icon: Ext.Msg.WARNING,
                        buttons: Ext.Msg.OK
                    });
            },
            failure: function(request) {
                lm.hide();
                this.getStore().reload();
                Ext.Msg.show({
                    title: 'Item de solicitação',
                    msg: 'Ocorreram erros removendo os itens selecionados.',
                    icon: Ext.Msg.WARNING,
                    buttons: Ext.Msg.OK
                });
            }
        })
    },
});

core.RestfulGrid.register(
    'rh.registration.forminformation.general.Restful',
    'rh.registration.forminformation.general.Grid'
);

